// src/pages/api/lead.ts
// Handles primary lead/inquiry form submissions, routed per `intent`.
// DO NOT edit this file per client — update src/lib/email.config.ts instead.
//
// The proposal wizard posts twice: `stage=partial` when the contact step is
// completed and `stage=complete` on the full submit (same `ref`). A partial is
// HELD rather than sent (src/lib/partials.ts): if the complete form arrives
// inside the hold it is released silently; if not, /api/partial-sweep emails
// it to EMAIL_CONFIG.partialRoutes — customer support, not sales. Pipedrive +
// Mailchimp are env-gated no-ops until their keys are set.

import type { APIRoute } from 'astro';
import { Resend } from 'resend';
import { EMAIL_CONFIG } from '~/lib/email.config';
import { sendWithAlert, notifySubmission, honeypotValue } from '~/lib/form-alert';
import { upsertMailchimpContact } from '~/lib/mailchimp';
import { holdPartial, releaseHeldFor, renderPartialEmail, partialSlackRows, formatCentral, type HeldPartial } from '~/lib/partials';


const resend = new Resend(import.meta.env.RESEND_API_KEY);
// Slack destination. Astro reads env via import.meta.env, so the routes pass
// this explicitly. FORM_SLACK_WEBHOOK is this client's own channel and takes
// precedence for BOTH submissions and failures; FORM_ALERT_SLACK_URL is the
// shared fallback for clients without a channel of their own.
const SLACK_WEBHOOK =
  import.meta.env.FORM_SLACK_WEBHOOK || import.meta.env.FORM_ALERT_SLACK_URL;
// Alloy's monitoring cc — empty once the site has a Slack channel (see email.config.ts).
const CC = EMAIL_CONFIG.ccAll;

// The form's structured per-intent answers (`fieldsJson`: a labeled, ordered
// list). Malformed input yields an empty list rather than an error.
function parseFields(raw: FormDataEntryValue | null): { label: string; value: string }[] {
  try {
    const parsed = JSON.parse(raw?.toString() ?? '[]');
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((f) => f && typeof f.label === 'string')
      .map((f) => ({ label: String(f.label), value: String(f.value ?? '').trim() }));
  } catch {
    return [];
  }
}

export const POST: APIRoute = async ({ request }) => {
  try {
    const data     = await request.formData();
    const name    = data.get('name')?.toString().trim()    ?? '';
    const email   = data.get('email')?.toString().trim()   ?? '';
    const phone   = data.get('phone')?.toString().trim()   ?? '';
    const company = data.get('company')?.toString().trim() ?? '';
    const source  = data.get('source')?.toString().trim()  ?? '';
    const intent  = data.get('intent')?.toString().trim()  ?? '';
    const ref     = data.get('ref')?.toString().trim()     ?? '';
    const message = data.get('message')?.toString().trim() ?? '';
    // stage: 'partial' = the wizard's contact step was completed but the form isn't
    // finished yet — HELD, see below; 'complete' (default) = full submit.
    const stage     = data.get('stage')?.toString().trim() ?? 'complete';
    const isPartial = stage === 'partial';

    // Per-intent content (subject + submitter confirmation) — see email.config.ts.
    const intentCfg = EMAIL_CONFIG.intents[intent] ?? EMAIL_CONFIG.intents.default;
    const detailFields = parseFields(data.get('fieldsJson'));
    // The wizard's step-1 role ("Board President", "Property owner / resident"…),
    // shown in the Slack heading for partials so they can be told apart at a glance.
    const leadRole = detailFields.find((f) => /^role$/i.test(f.label))?.value || '';

    // The Slack record: every answer, labelled, in the same order as the email.
    const slackRows: Array<[string, string]> = [
      ['Name', name], ['Email', email], ['Phone', phone], ['Company', company],
      ...detailFields.map((f): [string, string] => [f.label, f.value]),
      ['Message', message], ['Ref', ref], ['Intent', intent], ['Stage', stage], ['Source', source],
    ];

    // Honeypot filled → a bot, or a browser / password-manager autofill that took
    // the hidden field for a contact field. Nothing is sent either way (the bot
    // must not learn it was caught), but the discard is logged to Slack with the
    // answers, so a real person caught by autofill is visible and recoverable.
    const honeypot = honeypotValue(data);
    if (honeypot) {
      await notifySubmission({
        client: EMAIL_CONFIG.brand.name,
        slackWebhookUrl: SLACK_WEBHOOK,
        route: `${intentCfg.label}${isPartial ? ' (started)' : ''} — discarded`,
        formName: `${intent || 'lead'} form`,
        status: 'discarded',
        note: `value: ${JSON.stringify(honeypot.slice(0, 60))}`,
        fields: slackRows,
      });
      return new Response(JSON.stringify({ success: true }), { status: 200 });
    }

    if (!email || !name) {
      return new Response(JSON.stringify({ error: 'Name and email are required.' }), { status: 400 });
    }

    // Route the notification to the right inbox by intent (falls back to default).
    // A partial capture has its own destination (partialRoutes — customer support,
    // see email.config.ts); intents without one route like a complete submission.
    const notifyTo =
      (isPartial && EMAIL_CONFIG.partialRoutes[intent]) ||
      EMAIL_CONFIG.routes[intent] ||
      EMAIL_CONFIG.notify;

    // An intent with an explicitly empty route is accepted but intentionally NOT
    // delivered anywhere — no staff email, no confirmation, no Mailchimp.
    if (!notifyTo.length) {
      return new Response(JSON.stringify({ success: true }), { status: 200 });
    }

    // Render EVERY structured answer with its real label.
    const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const detailRows = detailFields
      .map((f) =>
        `<tr><td style="padding:4px 14px 4px 0;color:#888;white-space:nowrap;vertical-align:top"><strong>${esc(f.label)}</strong></td><td style="padding:4px 0">${f.value ? esc(f.value) : '—'}</td></tr>`)
      .join('');

    // ── Started, not finished ─────────────────────────────────────────────
    // Held for HOLD_MINUTES (src/lib/partials.ts) instead of sent. If the full
    // form arrives inside the hold, the complete path below releases it and
    // nobody hears about it twice; if it never arrives, /api/partial-sweep emails
    // customer support. No CRM deal, no Mailchimp tag until then. Without a store
    // (no BLOB_READ_WRITE_TOKEN) the partial is sent at once, still to the partial
    // route and still without a deal.
    if (isPartial) {
      const partial: HeldPartial = {
        ref, name, email, phone, company, role: leadRole, source, intent,
        createdAt: new Date().toISOString(),
      };
      const hold = intent === 'proposal' ? await holdPartial(partial) : { held: false as const, reason: 'only proposals are held' };
      const slackRoute = `${intentCfg.label} started, not finished${leadRole ? ` · ${leadRole}` : ''}`;
      if (hold.held) {
        await notifySubmission({
          client: EMAIL_CONFIG.brand.name,
          slackWebhookUrl: SLACK_WEBHOOK,
          route: slackRoute,
          formName: `${intent || 'lead'} form`,
          status: 'held',
          note: `If the form is not finished by ${formatCentral(hold.releaseAt)}, ${[notifyTo].flat().join(', ')} gets it; a finished form replaces it silently.`,
          fields: slackRows,
        });
        return new Response(JSON.stringify({ success: true, held: true, releaseAt: hold.releaseAt.toISOString() }), { status: 200 });
      }

      const { subject, html } = renderPartialEmail(partial, {
        held: false, label: intentCfg.label,
        completeTo: EMAIL_CONFIG.routes[intent] ?? EMAIL_CONFIG.notify,
      });
      try {
        await sendWithAlert(
          {
            client: EMAIL_CONFIG.brand.name,
            formName: `${intentCfg.label}${intent ? ` (${intent})` : ''} — partial`,
            slackWebhookUrl: SLACK_WEBHOOK,
            alertEmail: { apiKey: import.meta.env.RESEND_API_KEY, to: EMAIL_CONFIG.alertsTo, from: EMAIL_CONFIG.from.notifications },
          },
          () => resend.emails.send({
            from: EMAIL_CONFIG.from.notifications, replyTo: EMAIL_CONFIG.replyTo,
            to: notifyTo, ...(CC.length ? { cc: CC } : {}), subject, html,
          })
        );
      } catch (err) {
        await notifySubmission({
          client: EMAIL_CONFIG.brand.name, slackWebhookUrl: SLACK_WEBHOOK, route: slackRoute,
          formName: `${intent || 'lead'} form → ${[notifyTo].flat().join(', ')}`, delivered: false, fields: slackRows,
        });
        throw err;
      }
      if (intent === 'proposal') {
        await upsertMailchimpContact({
          email, firstName: name.split(' ')[0], lastName: name.split(' ').slice(1).join(' '), company,
          tags: [...EMAIL_CONFIG.mailchimp.defaultTags, 'proposal-incomplete'],
        });
      }
      await notifySubmission({
        client: EMAIL_CONFIG.brand.name, slackWebhookUrl: SLACK_WEBHOOK, route: slackRoute,
        formName: `${intent || 'lead'} form → ${[notifyTo].flat().join(', ')}`,
        status: 'delivered', note: `sent at once — hold unavailable (${hold.reason})`, fields: partialSlackRows(partial),
      });
      // `reason` says why the hold did not happen (no store, store error). It
      // carries no secret and makes a mis-set deployment diagnosable from a curl.
      return new Response(JSON.stringify({ success: true, held: false, reason: hold.reason }), { status: 200 });
    }

    // ── Complete submission ───────────────────────────────────────────────
    // Internal notification — alerts Slack + email if the send fails (then re-throws → 500).
    // The error is held rather than thrown so the Slack log below still runs;
    // it is re-thrown straight after, so the form still gets its 500.
    let notifyError: unknown = null;
    try {
      await sendWithAlert(
        {
          client: EMAIL_CONFIG.brand.name,
          formName: `${intentCfg.label}${intent ? ` (${intent})` : ''}`,
          slackWebhookUrl: SLACK_WEBHOOK,
          alertEmail: { apiKey: import.meta.env.RESEND_API_KEY, to: EMAIL_CONFIG.alertsTo, from: EMAIL_CONFIG.from.notifications },
        },
        () => resend.emails.send({
          from:    EMAIL_CONFIG.from.notifications,
          replyTo: EMAIL_CONFIG.replyTo,
          to:      notifyTo,
          ...(CC.length ? { cc: CC } : {}),
          subject: intentCfg.notifySubject(company || name),
          html: `
            <h2>${esc(intentCfg.label)}</h2>
            <p><strong>Name:</strong> ${esc(name)}</p>
            <p><strong>Email:</strong> ${esc(email)}</p>
            ${phone   ? `<p><strong>Phone:</strong> ${esc(phone)}</p>` : ''}
            ${company ? `<p><strong>Company:</strong> ${esc(company)}</p>` : ''}
            ${detailRows ? `<table style="border-collapse:collapse;margin:14px 0;font-size:14px">${detailRows}</table>` : ''}
            ${message ? `<p><strong>Message:</strong><br>${esc(message).replace(/\n/g, '<br>')}</p>` : ''}
            <hr><p style="color:#888;font-size:12px">${ref ? `Ref ${esc(ref)} · ` : ''}Form: ${esc(intent || 'lead')}${source ? ` · Source ${esc(source)}` : ''}</p>
          `,
        })
      );
    } catch (err) {
      notifyError = err;
    }

    // The Slack record. If the email failed, post it now (it is then the only
    // copy of the lead) and stop.
    const slackForm = `${intent || 'lead'} form → ${[notifyTo].flat().join(', ')}`;
    if (notifyError) {
      await notifySubmission({
        client: EMAIL_CONFIG.brand.name,
        slackWebhookUrl: SLACK_WEBHOOK,
        route: intentCfg.label,
        formName: slackForm,
        delivered: false,
        fields: slackRows,
      });
      throw notifyError;
    }

    // The complete form is the notification: drop any held partial for this
    // person (same email, any case, or the same ref) so support never hears about
    // a form that was finished. After the staff email, so a failed send never
    // loses the only copy.
    const superseded = intent === 'proposal' ? await releaseHeldFor(email, ref) : [];

    // Confirmation to submitter, with a recap of what they shared.
    const firstName = name.split(' ')[0] || name;
    const summaryBlock = (detailRows || message)
      ? `<hr style="border:none;border-top:1px solid #e5e5ef;margin:22px 0">
         <p style="font-size:13px;color:#888;margin:0 0 8px"><strong>What you shared with us</strong></p>
         ${detailRows ? `<table style="border-collapse:collapse;font-size:14px">${detailRows}</table>` : ''}
         ${message ? `<p style="font-size:14px;margin:12px 0 0"><strong>In your words:</strong><br>${esc(message).replace(/\n/g, '<br>')}</p>` : ''}`
      : '';
    const { error: confirmError } = await resend.emails.send({
      from:    EMAIL_CONFIG.from.hello,
      replyTo: EMAIL_CONFIG.replyTo,
      to:      email,
      subject: intentCfg.confirmSubject,
      html:    intentCfg.confirmBody(firstName, EMAIL_CONFIG.brand.url) + summaryBlock,
    });
    if (confirmError) console.error('Resend confirm error:', confirmError);

    // Mailchimp — COMPLETE proposal submissions only. (A started form that is
    // never finished is tagged `proposal-incomplete` by the sweep instead.)
    // Env-gated + never throws.
    if (intent === 'proposal') {
      await upsertMailchimpContact({
        email,
        firstName: name.split(' ')[0],
        lastName:  name.split(' ').slice(1).join(' '),
        company,
        tags: EMAIL_CONFIG.mailchimp.defaultTags,
      });
    }

    await notifySubmission({
      client: EMAIL_CONFIG.brand.name,
      slackWebhookUrl: SLACK_WEBHOOK,
      route: intentCfg.label,
      formName: slackForm,
      status: 'delivered',
      ...(superseded.length ? { note: `replaced the started form held earlier (${superseded.join(', ')}) — support was not emailed` } : {}),
      fields: slackRows,
    });

    return new Response(JSON.stringify({ success: true, superseded }), { status: 200 });
  } catch (err) {
    console.error('Lead API error:', err);
    return new Response(JSON.stringify({ error: 'Something went wrong. Please try again.' }), { status: 500 });
  }
};
